def flatten(items):
    result = []
    for item in items:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

print(flatten([1, [2, [3, 4]], 5]))

def make_validator(min_len, max_len):
    def validate(text):
        if len(text) < min_len:
            return f"en az {min_len} karakter"
        if len(text) > max_len:
            return f"en fazla {max_len} karakter"
        return "geçerli"
    return validate

username_check = make_validator(3, 8)
print(username_check("ab"))
print(username_check("ada_lovelace"))
print(username_check("ada"))

